import Foundation
import Testing
@testable import Mference
import MferenceValidationSupport

/// GGUF blocks against llama.cpp b1b770d9's own dequantization of them
/// (`ggml_get_type_traits()->to_float`, through `mf-dequant`), generated by
/// `Scripts/parity/gguf_make_quant_goldens.py`. Every Mference decoder of the
/// install's seven block types must reproduce llama.cpp bit for bit
/// (U5 layer 1):
/// - the llama.cpp-order reference (`GGUFReferenceDequant`);
/// - LUT4, through `GGUFLUT4Reference` and `GGUFLUT4.weight`;
/// - the runtime decoders in `GGUFBlockDecode` (Q6_K, Q8_0, IQ4_NL).
///
/// The committed fixture is seeded synthetic blocks built to hit the edge
/// cases (every grid and sign index, IQ4_XS ls = 32's signed zero, fp16 d at
/// ±0, subnormal and ±max); it holds no model data. The same checks run on
/// real blocks of the pinned Unsloth GGUF when `MFERENCE_GGUF_REAL_GOLDENS`
/// names a fixture made by the script's `real` mode. Those are model weights
/// and stay local.
@Suite struct GGUFQuantGoldensTests {
    static let committed: URL = {
        var root = URL(fileURLWithPath: #filePath)
        for _ in 0..<6 { root.deleteLastPathComponent() }
        return root.appendingPathComponent("Tests/Mference/Fixtures/gguf-quant")
    }()

    static var real: URL? {
        ProcessInfo.processInfo.environment["MFERENCE_GGUF_REAL_GOLDENS"].map { URL(fileURLWithPath: $0) }
    }

    static let names: [UInt32: String] = [8: "q8_0", 14: "q6_K", 18: "iq3_xxs", 20: "iq4_nl",
                                          22: "iq2_s", 23: "iq4_xs", 42: "q2_0"]

    /// Raw bytes of each tensor in a fixture's safetensors file.
    static func tensors(_ dir: URL) throws -> [String: [UInt8]] {
        let data = try [UInt8](Data(contentsOf: dir.appendingPathComponent("goldens.safetensors")))
        let headerLength = data[0..<8].enumerated().reduce(0) { $0 | Int($1.element) << (8 * $1.offset) }
        let header = try #require(JSONSerialization.jsonObject(with: Data(data[8..<(8 + headerLength)])) as? [String: Any])
        var out = [String: [UInt8]]()
        for (name, value) in header where name != "__metadata__" {
            let offsets = try #require((value as? [String: Any])?["data_offsets"] as? [Int])
            out[name] = Array(data[(8 + headerLength + offsets[0])..<(8 + headerLength + offsets[1])])
        }
        return out
    }

    static func manifest(_ dir: URL) throws -> [String: Any] {
        try #require(JSONSerialization.jsonObject(
            with: Data(contentsOf: dir.appendingPathComponent("goldens-manifest.json"))) as? [String: Any])
    }

    static func floatBits(_ bytes: [UInt8]) -> [UInt32] {
        stride(from: 0, to: bytes.count, by: 4).map {
            UInt32(bytes[$0]) | UInt32(bytes[$0 + 1]) << 8 | UInt32(bytes[$0 + 2]) << 16 | UInt32(bytes[$0 + 3]) << 24
        }
    }

    /// Every decoder of every type in `dir`, bit for bit against llama.cpp.
    static func checkAllDecoders(_ dir: URL) throws {
        let manifest = try manifest(dir)
        let reference = try #require(manifest["reference"] as? [String: Any])
        #expect(reference["llama_cpp_commit"] as? String == GGUFQuantTables.sourceCommit)
        let all = try tensors(dir)
        #expect(Set(all.keys.map { $0.components(separatedBy: ".")[0] }) == Set(names.values))

        for type in GGUFLUT4.SourceType.allCases {
            let name = try #require(names[type.rawValue])
            let blocks = try #require(all["\(name).blocks"])
            let want = floatBits(try #require(all["\(name).dequant"]))
            #expect(blocks.count % type.blockBytes == 0 && want.count == blocks.count / type.blockBytes * type.blockWeights)
            let (ref, lut4): ([Float], [Float]) = blocks.withUnsafeBytes { raw in
                let r: [Float] = switch type {
                case .iq3_xxs: GGUFReferenceDequant.iq3XXS(raw)
                case .iq2_s: GGUFReferenceDequant.iq2S(raw)
                case .iq4_xs: GGUFReferenceDequant.iq4XS(raw)
                case .iq4_nl: GGUFReferenceDequant.iq4NL(raw)
                case .q2_0: GGUFReferenceDequant.q2_0(raw)
                }
                return (r, GGUFLUT4Reference.dequantize(type, GGUFLUT4Reference.decompose(type, raw)))
            }
            #expect(ref.map(\.bitPattern) == want, "\(name): llama.cpp-order reference")
            #expect(lut4.map(\.bitPattern) == want, "\(name): LUT4")
            if type == .iq4_nl {
                let runtime = blocks.withUnsafeBytes { GGUFBlockDecode.dequantizeIQ4NL($0) }
                #expect(runtime.map(\.bitPattern) == want, "iq4_nl: GGUFBlockDecode")
            }
        }
        for (name, decode) in [("q6_K", GGUFBlockDecode.dequantizeQ6K), ("q8_0", GGUFBlockDecode.dequantizeQ8_0)] {
            let blocks = try #require(all["\(name).blocks"])
            let want = floatBits(try #require(all["\(name).dequant"]))
            let got = blocks.withUnsafeBytes { decode($0) }
            #expect(got.map(\.bitPattern) == want, "\(name): GGUFBlockDecode")
        }
    }

    @Test func committedFixtureIsSyntheticAndCarriesTheEdgeCases() throws {
        let manifest = try Self.manifest(Self.committed)
        #expect(manifest["kind"] as? String == "synthetic")
        #expect(manifest["source"] == nil, "the committed fixture must hold no model data")
        let all = try Self.tensors(Self.committed)
        // IQ4_XS ls = 32 gives llama.cpp's -0 for negative table entries.
        let iq4xs = Self.floatBits(try #require(all["iq4_xs.dequant"]))
        #expect(iq4xs.contains(0x8000_0000) && iq4xs.contains(0))
        // Q2_0 with q = 1 and a negative d gives -0.
        #expect(Self.floatBits(try #require(all["q2_0.dequant"])).contains(0x8000_0000))
        // Every IQ3_XXS (256) and IQ2_S (1024) grid index appears.
        let iq3 = try #require(all["iq3_xxs.blocks"])
        let iq3Indices = Set((0..<(iq3.count / 98)).flatMap { b in (0..<64).map { Int(iq3[b * 98 + 2 + $0]) } })
        #expect(iq3Indices.count == 256)
        let iq2 = try #require(all["iq2_s.blocks"])
        let iq2Indices = Set((0..<(iq2.count / 82)).flatMap { b in
            (0..<32).map { k in Int(iq2[b * 82 + 2 + k]) | ((Int(iq2[b * 82 + 66 + k / 4]) >> (2 * (k % 4))) & 3) << 8 }
        })
        #expect(iq2Indices.count == 1024)
    }

    @Test func committedSyntheticBlocksReproduceLlamaCpp() throws {
        try Self.checkAllDecoders(Self.committed)
    }

    @Test(.enabled(if: GGUFQuantGoldensTests.real != nil, "set MFERENCE_GGUF_REAL_GOLDENS to a local real-block fixture"))
    func realBlocksReproduceLlamaCpp() throws {
        let dir = try #require(Self.real)
        let manifest = try Self.manifest(dir)
        #expect(manifest["kind"] as? String == "real")
        let source = try #require(manifest["source"] as? [String: Any])
        #expect(source["commit"] as? String == "3f3ba9cb826b49c665510ce1702fd513a393ce39")
        try Self.checkAllDecoders(dir)
    }
}
